    rows, cols = len(grid), len(grid[0])
    sr, sc = start
    gr, gc = goal

    # helper to check cell validity
    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # start/goal validation
    if not (is_free(sr, sc) and is_free(gr, gc)):
        return [] if (sr, sc) != (gr, gc) else []
    if start == goal:
        return [start]

    # assign an index to each free cell
    idx = {}
    cells = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '.':
                i = r * cols + c
                idx[(r, c)] = i
                cells.append((r, c))

    n_free = len(cells)

    # build edge list (directed, both directions)
    edges = []
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    for r, c in cells:
        u = idx[(r, c)]
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if is_free(nr, nc):
                v = idx[(nr, nc)]
                edges.append((u, v))

    INF = 10**9
    dist = {i: INF for i in idx.values()}
    pred = {}
    start_id = idx[start]
    goal_id = idx[goal]
    dist[start_id] = 0

    # Bellman‑Ford style relaxation (unweighted graph)
    for _ in range(n_free - 1):
        updated = False
        for u, v in edges:
            if dist[u] + 1 < dist[v]:
                dist[v] = dist[u] + 1
                pred[v] = u
                updated = True
        if not updated:
            break

    if dist[goal_id] == INF:
        return []

    # reconstruct path using predecessor links
    path_ids = []
    cur = goal_id
    while cur != start_id:
        path_ids.append(cur)
        cur = pred.get(cur)
        if cur is None:
            return []   # safety, should not happen
    path_ids.append(start_id)
    path_ids.reverse()

    # convert ids back to (row, col) tuples
    rev_idx = {v: k for k, v in idx.items()}
    return [rev_idx[i] for i in path_ids]

