    visited = {cur}
    while cur != goal:
        r, c = cur
        # Order directions to approach the goal
        order = []
        if goal[0] > r:
            order.append((1, 0))   # down
        if goal[0] < r:
            order.append((-1, 0))  # up
        if goal[1] > c:
            order.append((0, 1))   # right
        if goal[1] < c:
            order.append((0, -1))  # left
        # Fill remaining directions to keep deterministic
        for d in DIRS:
            if d not in order:
                order.append(d)

        moved = False
        for dr, dc in order:
            nr, nc = r + dr, c + dc
            nxt = (nr, nc)
            if free(nr, nc) and nxt not in visited:
                cur = nxt
                path.append(cur)
                visited.add(cur)
                moved = True
                break
        if not moved:
            # No forward move; cannot progress further
            return []
    return path

