            break
        if d != dist[(r, c)]:
            continue  # stale entry
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if not in_bounds(nr, nc):
                continue
            if grid[nr][nc] == '#':
                continue
            nd = d + 1
            if (nr, nc) not in dist or nd < dist[(nr, nc)]:
                dist[(nr, nc)] = nd
                parent[(nr, nc)] = (r, c)
                heapq.heappush(heap, (nd, (nr, nc)))

    # Reconstruct path if goal was reached
    if goal not in parent and goal != start:
        return []
    path = []
    cur = goal
    while cur != start:
        path.append(cur)
        cur = parent.get(cur)
        if cur is None:
            return []  # disconnected
    path.append(start)
    path.reverse()
    return path

