from collections import deque
from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0]) if grid else 0

    def in_bounds(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols

    # Validate start and goal
    if not (in_bounds(*start) and in_bounds(*goal)):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    # BFS to find any path
    q = deque([start])
    prev = {start: None}          # maps a cell to its predecessor

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            nxt = (nr, nc)
            if not in_bounds(nr, nc):
                continue
            if grid[nr][nc] == '#':
                continue
            if nxt in prev:
                continue
            prev[nxt] = (r, c)
            if nxt == goal:
                # reconstruct path
                path = [goal]
                while path[-1] != start:
                    path.append(prev[path[-1]])
                path.reverse()
                return path
            q.append(nxt)

    # No path found
    return []

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    # helper to convert (r,c) <-> id
    def to_id(r, c):
        return r * cols + c
    def to_rc(idx):
        return divmod(idx, cols)

    # check start/goal validity
    sr, sc = start
    gr, gc = goal
    if not (0 <= sr < rows and 0 <= sc < cols and
            0 <= gr < rows and 0 <= gc < cols):
        return []
    if grid[sr][sc] == '#' or grid[gr][gc] == '#':
        return []
    if start == goal:
        return [start]

    # collect free cells
    free = []
    for r in range(rows):
        row = grid[r]
        for c in range(cols):
            if row[c] == '.':
                free.append(to_id(r, c))

    # map id -> index in UF; we will allocate UF for all cells but ignore walls
    total = rows * cols
    parent = list(range(total))
    rank = [0] * total
    tree_parent = {}          # child -> parent in the spanning forest

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        # union by rank, attach ry under rx
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        tree_parent[ry] = rx   # record tree edge

    # build edges between orthogonal free neighbours (right & down to avoid duplicates)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '.':
                continue
            cur = to_id(r, c)
            if c + 1 < cols and grid[r][c + 1] == '.':
                union(cur, to_id(r, c + 1))
            if r + 1 < rows and grid[r + 1][c] == '.':
                union(cur, to_id(r + 1, c))

    start_id = to_id(sr, sc)
    goal_id = to_id(gr, gc)

    if find(start_id) != find(goal_id):
        return []  # no connection

    # build ancestor chain for start
    anc_start = []
    cur = start_id
    while True:
        anc_start.append(cur)
        if cur in tree_parent:
            cur = tree_parent[cur]
        else:
            break

    # walk from goal upwards until meeting start's ancestors
    anc_goal = []
    cur = goal_id
    lca = None
    start_anc_set = set(anc_start)
    while True:
        anc_goal.append(cur)
        if cur in start_anc_set:
            lca = cur
            break
        if cur in tree_parent:
            cur = tree_parent[cur]
        else:
            break  # should not happen when connected

    if lca is None:
        return []  # safety fallback

    # construct path ids: start -> ... -> lca -> ... -> goal
    path_ids = []
    cur = start_id
    while cur != lca:
        path_ids.append(cur)
        cur = tree_parent[cur]
    path_ids.append(lca)

    for node in reversed(anc_goal):
        if node == lca:
            continue
        path_ids.append(node)

    # convert ids back to (row, col) tuples
    return [to_rc(i) for i in path_ids]

import heapq
from typing import List, Tuple

def solve(grid: List[str],
          start: Tuple[int, int],
          goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0]) if grid else 0

    def inside(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols

    # validation
    if not (inside(*start) and inside(*goal)):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    # uniform‑cost search (Dijkstra with all edges weight 1)
    heap = [(0, start)]
    came_from = {start: None}
    cost_so_far = {start: 0}
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while heap:
        _, current = heapq.heappop(heap)

        if current == goal:
            break

        cr, cc = current
        for dr, dc in directions:
            nr, nc = cr + dr, cc + dc
            nxt = (nr, nc)
            if not inside(nr, nc):
                continue
            if grid[nr][nc] == '#':
                continue
            new_cost = cost_so_far[current] + 1
            if nxt not in cost_so_far or new_cost < cost_so_far[nxt]:
                cost_so_far[nxt] = new_cost
                heapq.heappush(heap, (new_cost, nxt))
                came_from[nxt] = current

    if goal not in came_from:
        return []

    # reconstruct path
    path = []
    node = goal
    while node is not None:
        path.append(node)
        node = came_from[node]
    path.reverse()
    return path

